  ) v(linha, texto, uf, nome, municipio, uf_cadastro) LOOP
    SELECT b.id INTO v_id FROM public.emenda_beneficiarios b
     WHERE b.ativo AND b.nome = r.nome AND b.entrega_uf = r.uf_cadastro
       AND (b.entrega_municipio = r.municipio OR (r.municipio IS NULL AND b.entrega_municipio IS NULL));
    IF v_id IS NULL THEN
      RAISE EXCEPTION 'Cadastro % (%/%) não achado.', r.nome, r.municipio, r.uf_cadastro;
    END IF;
    v_total := v_total + public.fisc_ligar_nome_ao_cadastro(r.texto, r.uf, v_id, 'rodada 6');
    v_id := NULL;
  END LOOP;
  RAISE NOTICE 'Rodada 6: % cadastros novos, % itens ligados', v_novos, v_total;
END $$;
